WITH lines AS (SELECT id, created_at, EXPLODE(coupon_codes) AS code FROM carts) SELECT code, DATE_TRUNC('DAY', created_at) AS activity_day, COUNT(*) FILTER (WHERE code = 'BUNDLE') AS bundle_rows, MAX(created_at) AS last_seen, COUNT(CASE WHEN code = 'VIP' THEN 1 END) AS vip_count, COUNT(CASE WHEN code = 'WELCOME5' THEN 1 END) AS welcome5_count, SORT_ARRAY(COLLECT_SET(code)) AS code_list FROM lines GROUP BY GROUPING SETS ((code, DATE_TRUNC('DAY', created_at)), (code), ()) HAVING COUNT(CASE WHEN code = 'VIP' THEN 1 END) < 1000 ORDER BY activity_day NULLS FIRST
